-- Synthetic, rollback-only coverage. No network or actual email delivery.
begin;
do $$
declare own_jwt text; buyer_jwt text; guest_jwt text; uid uuid; buyer uuid; guest uuid; sid uuid;
 content uuid; other_content uuid; retail_content uuid; room uuid; other_room uuid; file uuid; other_file uuid; pending uuid;
 payload jsonb; result jsonb; g public.ig_room_grants; guest_grant public.ig_room_grants;
 denied boolean; b uuid=gen_random_uuid(); secret text=repeat('w',64); mail jsonb; lease jsonb;
 client jsonb; other_client jsonb; contact jsonb; duplicate_contact jsonb; engagement jsonb; engagement_room uuid;
 count_before int; saved_profile public.ig_profiles;
begin
 select u.id,jsonb_build_object('sub',u.id,'session_id',s.id,'role','authenticated','aal','aal2')::text into uid,own_jwt
 from auth.users u join auth.sessions s on s.user_id=u.id where u.email='owner@example.invalid' limit 1;
 select u.id,jsonb_build_object('sub',u.id,'session_id',s.id,'role','authenticated','aal','aal1')::text into buyer,buyer_jwt
 from auth.users u join auth.sessions s on s.user_id=u.id where u.email='buyer@example.invalid' limit 1;
 update public.ig_profiles set policy_version=ig_private.current_policy(),must_change_password=false where id=buyer;
 insert into public.ig_consents(user_id,purpose,granted,version,policy_hash) select buyer,'registration',true,version,sha256 from public.ig_policy_releases where current;
 update ig_private.integration_root set secret_hash=encode(extensions.digest(secret,'sha256'),'hex');
 insert into ig_private.room_config(broker_secret_hash) values(encode(extensions.digest(secret,'sha256'),'hex')) on conflict(id) do update set broker_secret_hash=excluded.broker_secret_hash;
 perform set_config('request.jwt.claims',own_jwt,true);
 insert into public.ig_content(kind,slug,title,practice) values('opportunity','admin-share-fixture','Private property','real-estate') returning id into content;
 insert into public.ig_content(kind,slug,title,practice) values('product','admin-share-other','Private catalogue','horeca') returning id into other_content;
 insert into public.ig_data_rooms(content_id,title) values(content,'Private property') returning id into room;
 insert into public.ig_data_rooms(content_id,title) values(other_content,'Private catalogue') returning id into other_room;
 insert into public.ig_room_files(room_id,name,object_key,mime,bytes,status,download_enabled)
 values(room,'Brief.pdf','synthetic/admin-share/brief','application/pdf',100,'ready',true) returning id into file;
 insert into public.ig_room_files(room_id,name,object_key,mime,bytes,status,download_enabled)
 values(other_room,'Other.pdf','synthetic/admin-share/other','application/pdf',100,'ready',true) returning id into other_file;
 payload=jsonb_build_object('action','share','access_basis','admin_authorised','room_id',room,'batch_id',b,
 'recipient_ids','[]'::jsonb,'recipients',jsonb_build_array(jsonb_build_object('name','Selected buyer','email',' BUYER@example.invalid ')),
 'authorisation_reason','Authorised private evaluation before NDA','confirm_authorisation',true,'download_mode','none','expires_at',now()+interval '20 days');
 select count(*) into count_before from public.ig_nda_requests;
 denied=false;begin perform public.ig_room_share(payload-'confirm_authorisation');exception when raise_exception then denied=true;end;assert denied,'Missing administrator attestation accepted';
 denied=false;begin perform public.ig_room_share(payload||'{"authorisation_reason":""}');exception when raise_exception then denied=true;end;assert denied,'Missing reason accepted';
 denied=false;begin perform public.ig_room_share(payload||jsonb_build_object('recipients',jsonb_build_array(jsonb_build_object('email','bad<email>@example.com'))));exception when raise_exception then denied=true;end;assert denied,'Unsafe recipient accepted';
 assert not has_table_privilege('authenticated','public.ig_room_grants','INSERT');
 assert not has_table_privilege('authenticated','public.ig_room_grants','UPDATE');
 assert not has_function_privilege('authenticated','ig_private.room_share_before_admin_authority(jsonb)','EXECUTE');
 assert not has_function_privilege('anon','public.ig_room_share(jsonb)','EXECUTE');
 perform set_config('request.jwt.claims',buyer_jwt,true);
 denied=false;begin perform public.ig_room_share(payload);exception when insufficient_privilege then denied=true;end;assert denied,'Client self-authorised';
 -- Being an administrator in another practice does not authorise this room.
 select * into saved_profile from public.ig_profiles where id=buyer;
 update public.ig_profiles set roles=array['administrator'],practice_grants='{"horeca":["read","data_rooms"]}' where id=buyer;
 perform set_config('request.jwt.claims',(buyer_jwt::jsonb||'{"aal":"aal2"}')::text,true);
 denied=false;begin perform public.ig_room_share(payload);exception when insufficient_privilege then denied=true;end;assert denied,'Cross-practice administrator authorised the room';
 update public.ig_profiles set roles=saved_profile.roles,practice_grants=saved_profile.practice_grants where id=buyer;
 perform set_config('request.jwt.claims',own_jwt,true);
 insert into public.ig_room_files(room_id,name,object_key,mime,bytes,status) values(room,'Pending.pdf','synthetic/admin-share/pending','application/pdf',100,'pending') returning id into pending;
 denied=false;begin perform public.ig_room_share(payload);exception when raise_exception then denied=true;end;assert denied,'Pending file shared';
 delete from public.ig_room_files where id=pending;
 result=public.ig_room_share(payload);
 assert result->>'added'='1' and result->>'queued'='1';
 assert public.ig_room_share(payload)=result,'Retry duplicated the grant or email';
 denied=false;begin perform public.ig_room_share(payload||'{"download_mode":"all"}');exception when raise_exception then denied=true;end;assert denied,'Changed idempotency payload accepted';
 assert (select count(*) from public.ig_nda_requests)=count_before,'Administrator authority fabricated an NDA';
 select * into strict g from public.ig_room_grants where room_id=room and recipient_email='buyer@example.invalid';
 assert g.authorised_by=uid and g.nda_request_id is null and g.contact_id is null and g.download_mode='none';
 result=public.ig_room_share(payload||jsonb_build_object('batch_id',gen_random_uuid(),'download_mode','all'));
 assert result->>'recent'='1' and result->>'queued'='0';
 assert (select download_mode='none' from public.ig_room_grants where id=g.id),'Repeated share broadened active access';
 perform set_config('request.jwt.claims',buyer_jwt,true);
 assert ig_private.room_access(room) and not ig_private.room_access(other_room),'Direct grant crossed room boundary';
 assert jsonb_array_length(public.ig_room_dashboard(jsonb_build_object('id',room)))=1,'Direct grant missing from client dashboard';
 execute 'set local role authenticated';
 assert (select count(*) from public.ig_room_grants)=0,'Client enumerated administrator grant records';
 assert jsonb_array_length(public.ig_room_dashboard(jsonb_build_object('id',room)))=1,'Authenticated role cannot open authorised room';
 execute 'set local role none';
 assert public.ig_room_authorize(jsonb_build_object('action','preview_source','id',file,'broker_secret',secret))->>'id'=file::text,'Authorised preview failed';
 assert not ig_private.room_download(file),'View-only grant downloaded';
 denied=false;begin perform public.ig_room_authorize(jsonb_build_object('action','download','id',file));exception when insufficient_privilege then denied=true;end;assert denied;
 denied=false;begin perform public.ig_room_authorize(jsonb_build_object('action','preview_source','id',other_file,'broker_secret',secret));exception when insufficient_privilege then denied=true;end;assert denied,'Preview crossed room boundary';
 assert not public.ig_retail_can_upload(room),'Direct share granted upload rights';
 denied=false;begin perform public.ig_room_manage(jsonb_build_object('action','upload_prepare','room_id',room,'name','Client.pdf','mime','application/pdf','bytes',100));exception when insufficient_privilege then denied=true;end;assert denied,'Direct recipient uploaded without upload grant';
 denied=false;begin perform public.ig_room_manage(to_jsonb(g)||'{"action":"grant_update","active":true,"download_mode":"all"}');exception when insufficient_privilege then denied=true;end;assert denied,'Client broadened own grant';
 update auth.users set email='different@example.invalid' where id=buyer;
 assert not ig_private.room_access(room),'Changed authenticated email retained grant';
 update auth.users set email='buyer@example.invalid',email_confirmed_at=null where id=buyer;
 assert not ig_private.room_access(room),'Unverified identity admitted';
 update auth.users set email_confirmed_at=now() where id=buyer;
 update public.ig_profiles set must_change_password=true where id=buyer;
 assert not ig_private.room_access(room),'Initial password requirement bypassed';
 update public.ig_profiles set must_change_password=false,status='suspended' where id=buyer;
 assert not ig_private.room_access(room),'Disabled profile admitted';
 update public.ig_profiles set status='active' where id=buyer;
 update public.ig_data_rooms set active=false where id=room;
 assert not ig_private.room_access(room) and not ig_private.room_notice_eligible(room,null,null,g.recipient_email,g.id);
 update public.ig_data_rooms set active=true where id=room;
 update public.ig_content set status='archived' where id=content;
 assert not ig_private.room_access(room),'Archived property admitted';
 update public.ig_content set status='draft' where id=content;
 update public.ig_room_grants set expires_at=now()-interval '1 second' where id=g.id;
 assert not ig_private.room_access(room),'Expired authority admitted';
 perform set_config('request.jwt.claims',own_jwt,true);
 select * into g from public.ig_room_grants where id=g.id;
 perform public.ig_room_manage(to_jsonb(g)||'{"action":"grant_update","active":false}');
 assert not ig_private.room_notice_eligible(room,null,null,g.recipient_email,g.id),'Revoked authority emailed';
 result=public.ig_room_share(payload||jsonb_build_object('action','access','batch_id',gen_random_uuid(),'download_mode','selected'));
 assert result->>'renewed'='1' and result->>'queued'='0';
 select * into g from public.ig_room_grants where id=g.id;
 perform public.ig_room_manage(jsonb_build_object('action','file_rule','grant_id',g.id,'version',g.version,'file_id',file,'rule','allow'));
 perform set_config('request.jwt.claims',buyer_jwt,true);
 assert ig_private.room_download(file),'Selected explicit download unavailable';
 update public.ig_room_files set download_enabled=false where id=file;
 assert not ig_private.room_download(file),'File download setting bypassed';
 update public.ig_room_files set download_enabled=true where id=file;
 perform set_config('request.jwt.claims',own_jwt,true);
 -- Arbitrary new email gets an invitation, then access only after verified signup.
 payload=payload||jsonb_build_object('batch_id',gen_random_uuid(),'recipients',jsonb_build_array(jsonb_build_object('name','Future guest','email','new-room-guest@example.com')));
 result=public.ig_room_share(payload);
 assert result->>'added'='1' and result->>'queued'='1';
 select * into guest_grant from public.ig_room_grants where room_id=room and recipient_email='new-room-guest@example.com';
 assert public.ig_client_login_eligible(secret,'NEW-ROOM-GUEST@example.com'),'Invited guest cannot request first email code';
 update public.ig_room_grants set active=false where id=guest_grant.id;
 assert not public.ig_client_login_eligible(secret,'new-room-guest@example.com'),'Revoked invitation still enables first signup';
 update public.ig_room_grants set active=true where id=guest_grant.id;
 assert not public.ig_client_login_eligible(secret,'not-invited@example.invalid');
 assert ig_private.room_notice_eligible(room,null,null,guest_grant.recipient_email,guest_grant.id),'Pre-registration invitation unavailable';
 assert not ig_private.room_notice_eligible(other_room,null,null,guest_grant.recipient_email,guest_grant.id),'Email eligibility crossed rooms';
 assert not ig_private.room_notice_eligible(room,null,null,'other@example.invalid',guest_grant.id),'Email eligibility crossed recipients';
 perform set_config('request.jwt.claims',buyer_jwt,true);
 assert not ig_private.grant_valid(guest_grant.id),'Other signed-in user inherited invitation';
 insert into auth.users(email) values('new-room-guest@example.com') returning id into guest;
 insert into auth.sessions(user_id) values(guest) returning id into sid;
 guest_jwt=jsonb_build_object('sub',guest,'session_id',sid,'role','authenticated','aal','aal1')::text;
 perform set_config('request.jwt.claims',guest_jwt,true);
 assert not ig_private.room_access(room),'Unverified new guest admitted';
 update auth.users set email_confirmed_at=now() where id=guest;
 assert not ig_private.room_access(room),'Guest entered before registration policy acceptance';
 update public.ig_profiles set policy_version=ig_private.current_policy(),must_change_password=false where id=guest;
 insert into public.ig_consents(user_id,purpose,granted,version,policy_hash) select guest,'registration',true,version,sha256 from public.ig_policy_releases where current;
 assert ig_private.room_access(room),'Verified invited guest cannot open room';
 perform set_config('request.jwt.claims',own_jwt,true);
 client=public.ig_client_manage('{"action":"client_save","name":"Direct recipient client","practice":"hospitality","stage":"engaged"}');
 contact=public.ig_client_manage(jsonb_build_object('action','contact_save','client_id',client->'id','name','Future guest','email','new-room-guest@example.com','portal_enabled',true,'circulation',true));
 result=public.ig_room_share(payload||jsonb_build_object('action','access','batch_id',gen_random_uuid()));
 assert result->>'added'='0' and (select recipient_contact_id=(contact->>'id')::uuid from public.ig_room_grants where id=guest_grant.id),'Guest-to-CRM transition failed';
 update public.ig_client_contacts set circulation=false where id=(contact->>'id')::uuid;
 denied=false;begin perform public.ig_room_share(payload||jsonb_build_object('batch_id',gen_random_uuid()));exception when raise_exception then denied=true;end;assert denied,'Typed email bypassed circulation preference';
 assert not ig_private.room_notice_eligible(room,null,null,guest_grant.recipient_email,guest_grant.id),'Queued mail ignored updated preference';
 result=public.ig_room_share(payload||jsonb_build_object('action','access','batch_id',gen_random_uuid()));
 assert result->>'queued'='0','Access-only sent opted-out email';
 other_client=public.ig_client_manage('{"action":"client_save","name":"Second contact client","practice":"hospitality","stage":"engaged"}');
 duplicate_contact=public.ig_client_manage(jsonb_build_object('action','contact_save','client_id',other_client->'id','name','Duplicate guest','email','new-room-guest@example.com','portal_enabled',true,'circulation',true));
 denied=false;begin perform public.ig_room_share(payload||jsonb_build_object('batch_id',gen_random_uuid(),'recipients','[]'::jsonb,'recipient_ids',jsonb_build_array(duplicate_contact->'id')));exception when raise_exception then denied=true;end;assert denied,'Selected duplicate contact bypassed email preference';
 update public.ig_client_contacts set circulation=true where id=(contact->>'id')::uuid;
 perform set_config('request.jwt.claims',guest_jwt,true);
 update public.ig_client_contacts set active=false where id=(contact->>'id')::uuid;
 assert not ig_private.room_access(room),'Disabled CRM contact admitted';
 update public.ig_client_contacts set active=true where id=(contact->>'id')::uuid;
 update public.ig_clients set stage='archived' where id=(client->>'id')::uuid;
 assert not ig_private.room_access(room),'Archived recipient client admitted';
 update public.ig_clients set stage='engaged' where id=(client->>'id')::uuid;
 perform set_config('request.jwt.claims',own_jwt,true);
 engagement=public.ig_client_manage(jsonb_build_object('action','engagement_save','client_id',client->'id','title','Pre-terms engagement room','service','feasibility','reference','Fixture'));
 select id into engagement_room from public.ig_data_rooms where engagement_id=(engagement->>'id')::uuid;
 result=public.ig_room_share(payload||jsonb_build_object('room_id',engagement_room,'action','access','batch_id',gen_random_uuid(),'recipients',jsonb_build_array(jsonb_build_object('email','buyer@example.invalid'))));
 assert result->>'added'='1';
 assert not (select confidentiality_confirmed from public.ig_engagements where id=(engagement->>'id')::uuid),'Direct authority falsely confirmed engagement terms';
 perform set_config('request.jwt.claims',buyer_jwt,true);
 assert ig_private.room_access(engagement_room),'Direct authority cannot open engagement room';
 update public.ig_engagements set active=false where id=(engagement->>'id')::uuid;
 assert not ig_private.room_access(engagement_room),'Inactive engagement admitted';
 update public.ig_engagements set active=true where id=(engagement->>'id')::uuid;
 update public.ig_clients set stage='archived' where id=(client->>'id')::uuid;
 assert not ig_private.room_access(engagement_room),'Archived principal client admitted';
 update public.ig_clients set stage='engaged' where id=(client->>'id')::uuid;
 perform set_config('request.jwt.claims',own_jwt,true);
 insert into public.ig_content(kind,slug,title,practice) values('retail_space','admin-share-retail','Private retail mandate','retail-leasing') returning id into retail_content;
 insert into public.ig_retail_accounts(content_id,engagement_id) values(retail_content,(engagement->>'id')::uuid);
 perform set_config('request.jwt.claims',buyer_jwt,true);
 assert ig_private.room_access(engagement_room),'Active retail parent room inaccessible';
 update public.ig_content set status='archived' where id=retail_content;
 assert not ig_private.room_access(engagement_room),'Archived retail mandate retained direct room access';
 update public.ig_content set status='draft',deleted_at=now() where id=retail_content;
 assert not ig_private.room_access(engagement_room),'Deleted retail mandate retained direct room access';
 perform set_config('request.jwt.claims',own_jwt,true);
 result=public.ig_room_share(payload||jsonb_build_object('room_id',other_room,'action','access','batch_id',gen_random_uuid(),'recipients',jsonb_build_array(jsonb_build_object('email','buyer@example.invalid'))));
 assert result->>'added'='1','Non-property private catalogue could not be shared';
 perform set_config('request.jwt.claims',buyer_jwt,true);
 assert ig_private.room_access(other_room),'Non-property recipient cannot open shared room';
 perform set_config('request.jwt.claims',own_jwt,true);
 -- Existing queue checks the exact recipient grant again when the worker prepares.
 mail=public.ig_delivery(secret,jsonb_build_object('action','claim','circulation_batch',payload->>'batch_id'));
 assert jsonb_array_length(mail)=1 and mail->0->>'recipient'='new-room-guest@example.com','Worker did not claim the selected recipient';
 lease=mail->0;
 select * into guest_grant from public.ig_room_grants where id=guest_grant.id;
 perform public.ig_room_manage(to_jsonb(guest_grant)||'{"action":"grant_update","active":false}');
 denied=false;begin perform public.ig_delivery(secret,jsonb_build_object('action','prepare','id',lease->'id','lease_token',lease->'lease_token','payload',jsonb_build_object('to',jsonb_build_array('new-room-guest@example.com'))));exception when raise_exception then denied=true;end;assert denied,'Revoked grant delivered after claim';
 assert not public.ig_client_login_eligible(secret,'not-invited@example.invalid');
 -- All-or-nothing batch validation leaves no new recipient grant behind.
 denied=false;begin perform public.ig_room_share(payload||jsonb_build_object('batch_id',gen_random_uuid(),'recipients',jsonb_build_array(jsonb_build_object('email','valid-batch@example.invalid'),jsonb_build_object('email','invalid'))));exception when raise_exception then denied=true;end;assert denied;
 assert not exists(select 1 from public.ig_room_grants where recipient_email='valid-batch@example.invalid'),'Mixed invalid batch partially shared';
end $$;
rollback;
